const fs = require('fs');

const input = fs.readFileSync(0, 'utf8');
const len = input.length;
let pos = 0;

function nextInt() {
  while (pos < len) {
    const c = input.charCodeAt(pos);
    if (c >= 48 && c <= 57) break;
    pos++;
  }
  let x = 0;
  while (pos < len) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    x = x * 10 + (c - 48);
    pos++;
  }
  return x;
}

const n = nextInt();
const k = nextInt();

// Prefix sums: P[j] = X_1 + ... + X_j (não-decrescente, pois X_i >= 0)
const P = new Int32Array(n + 1);
let acc = 0;
for (let i = 1; i <= n; i++) {
  acc += nextInt();
  P[i] = acc;
}

// Conta pares (i, j) com i < j e P[j] - P[i] = K.
// Como P é não-decrescente, para cada j os índices i com P[i] = P[j] - K
// formam um bloco contíguo [lo, hi) dentro de [0, j-1]. Como
// t = P[j] - K é não-decrescente, lo e hi só avançam: O(N) total.
let lo = 0, hi = 0, ans = 0;
for (let j = 1; j <= n; j++) {
  const t = P[j] - k;
  // hi: primeiro índice com P[hi] > t (limitado a j, pois i <= j-1)
  while (hi < j && P[hi] <= t) hi++;
  // lo: primeiro índice com P[lo] >= t
  while (lo < hi && P[lo] < t) lo++;
  ans += hi - lo;
}

process.stdout.write(String(ans) + '\n');
